// Ленты берутся из automation/sources.json. Вставьте актуальный список сюда
// или подгрузите файл HTTP-нодой из репозитория. Один item = одна лента.
const feeds = [
  { name: 'The Robot Report', lang: 'en', weight: 3, feedUrl: 'https://www.therobotreport.com/feed/' },
  { name: 'Google News — cleaning robot', lang: 'en', weight: 2, feedUrl: 'https://news.google.com/rss/search?q=%22cleaning+robot%22+OR+%22autonomous+scrubber%22+warehouse+OR+mall+OR+facility&hl=en-US&gl=US&ceid=US:en' }
];
return feeds.map((f) => ({ json: f }));

// Фильтр релевантности + дедупликация (в т.ч. между запусками через static data).
const KEYWORDS = ['cleaning robot','autonomous scrubber','floor scrubber','robotic cleaning','warehouse cleaning','facility automation','janitorial robot','disinfection robot','window cleaning robot'];
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = ((j.title||'') + ' ' + (j.contentSnippet||j.content||'')).toLowerCase();
  const hits = KEYWORDS.filter((k) => text.includes(k)).length;
  if (hits < 1) continue; // нерелевантно
  const link = j.link || j.guid || '';
  const key = (j.title||'').toLowerCase().replace(/\W+/g,' ').trim().slice(0,120);
  if (!key || store.seen[key]) continue; // дубль
  store.seen[key] = Date.now();
  out.push({ json: { title: j.title, summary: (j.contentSnippet||j.content||'').slice(0,600), link, publishedAt: j.isoDate || j.pubDate || null } });
}
return out;

