// Парсим ответ Claude и собираем Markdown по контракту (см. content-contract.md).
function ymd(d){ const x = d? new Date(d): new Date(); return x.toISOString().slice(0,10); }
const out = [];
for (const item of $input.all()) {
  const src = item.json; // исходная новость
  let txt = '';
  try { txt = src.content?.[0]?.text || src.data?.content?.[0]?.text || ''; } catch(e){}
  if (!txt && typeof src === 'object' && src.content && Array.isArray(src.content)) txt = src.content[0].text;
  let a; try { a = JSON.parse(txt.match(/\{[\s\S]*\}/)[0]); } catch(e){ continue; }
  if (!a || a.skip) continue;
  const meta = $('Фильтр + дедуп').all()[item.pairedItem?.item ?? 0]?.json || {};
  const slug = (a.slug || a.title).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'').slice(0,60);
  const fm = [
    '---',
    'title: ' + JSON.stringify(a.title),
    'description: ' + JSON.stringify(a.description),
    'pubDate: ' + ymd(),
    'category: ' + JSON.stringify(a.category || 'Технологии'),
    'rubric: "Новости"',
    'tags: ' + JSON.stringify(a.tags || []),
    'objectTypes: ' + JSON.stringify(a.objectTypes || []),
    'vendors: ' + JSON.stringify(a.vendors || []),
    'robotType: ' + JSON.stringify(a.robotType || []),
    'readingTime: 2',
    'animation: ' + JSON.stringify(a.animation || 'robot-roll'),
    'origin: "auto"',
    'source:',
    '  name: ' + JSON.stringify(meta.sourceName || 'Источник'),
    '  url: ' + JSON.stringify(meta.link || ''),
    '  publishedAt: ' + ymd(meta.publishedAt),
    '---',
    '',
    a.body_md || ''
  ].join('\n');
  out.push({ json: { path: 'src/content/articles/news-' + slug + '.md', content: fm, message: 'news: ' + a.title } });
}
return out;
